using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextHelper
    {
        public static SchoolContext CreateContext(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static SchoolContext CreateSeededContext(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var context = CreateContext(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = DateTime.Parse("2007-09-01")
            };
            context.Departments.Add(dept);

            var instructor = new Instructor
            {
                ID = 1,
                LastName = "Smith",
                FirstMidName = "John",
                HireDate = DateTime.Parse("2000-01-15"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);

            dept.InstructorID = instructor.ID;

            var course1 = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 4022,
                Title = "Microeconomics",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            context.Courses.AddRange(course1, course2);

            var student1 = new Student
            {
                ID = 1,
                LastName = "Alexander",
                FirstMidName = "Carson",
                EnrollmentDate = DateTime.Parse("2010-09-01"),
                Enrollments = new System.Collections.Generic.List<Enrollment>()
            };
            var student2 = new Student
            {
                ID = 2,
                LastName = "Alonso",
                FirstMidName = "Meredith",
                EnrollmentDate = DateTime.Parse("2012-09-01"),
                Enrollments = new System.Collections.Generic.List<Enrollment>()
            };
            context.Students.AddRange(student1, student2);

            context.Enrollments.Add(new Enrollment
            {
                EnrollmentID = 1,
                StudentID = 1,
                CourseID = 1050,
                Grade = Grade.A
            });

            var ca = new CourseAssignment
            {
                CourseID = 1050,
                InstructorID = 1
            };
            context.CourseAssignments.Add(ca);
            instructor.CourseAssignments.Add(ca);

            context.OfficeAssignments.Add(new OfficeAssignment
            {
                InstructorID = 1,
                Location = "Smith 17"
            });

            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Fact]
        public void FullName_WithLastAndFirst_ReturnsConcatenated()
        {
            // Arrange
            var student = new Student { LastName = "Smith", FirstMidName = "John" };

            // Act
            var fullName = student.FullName;

            // Assert
            Assert.Equal("Smith, John", fullName);
        }

        [Fact]
        public void FullName_WithDifferentNames_ReturnsConcatenated()
        {
            var instructor = new Instructor { LastName = "Doe", FirstMidName = "Jane" };

            Assert.Equal("Doe, Jane", instructor.FullName);
        }

        [Fact]
        public void ID_SetAndGet_ReturnsValue()
        {
            var student = new Student { ID = 42 };

            Assert.Equal(42, student.ID);
        }
    }

    public class StudentTests
    {
        [Fact]
        public void EnrollmentDate_SetAndGet_ReturnsValue()
        {
            var date = new System.DateTime(2023, 9, 1);
            var student = new Student { EnrollmentDate = date };

            Assert.Equal(date, student.EnrollmentDate);
        }

        [Fact]
        public void Enrollments_DefaultNull_IsNull()
        {
            var student = new Student();

            Assert.Null(student.Enrollments);
        }

        [Fact]
        public void Enrollments_Initialized_CanAddItems()
        {
            var student = new Student
            {
                Enrollments = new System.Collections.Generic.List<Enrollment>()
            };
            student.Enrollments.Add(new Enrollment { EnrollmentID = 1 });

            Assert.Single(student.Enrollments);
            Assert.Equal(1, ((System.Collections.Generic.List<Enrollment>)student.Enrollments)[0].EnrollmentID);
        }
    }

    public class InstructorTests
    {
        [Fact]
        public void HireDate_SetAndGet_ReturnsValue()
        {
            var date = new System.DateTime(2000, 3, 15);
            var instructor = new Instructor { HireDate = date };

            Assert.Equal(date, instructor.HireDate);
        }

        [Fact]
        public void CourseAssignments_Initialized_CanAddItems()
        {
            var instructor = new Instructor
            {
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            instructor.CourseAssignments.Add(new CourseAssignment { CourseID = 100, InstructorID = 1 });

            Assert.Single(instructor.CourseAssignments);
        }

        [Fact]
        public void OfficeAssignment_SetAndGet_ReturnsValue()
        {
            var office = new OfficeAssignment { Location = "Room 101" };
            var instructor = new Instructor { OfficeAssignment = office };

            Assert.Equal("Room 101", instructor.OfficeAssignment.Location);
        }
    }

    public class CourseTests
    {
        [Fact]
        public void Course_Properties_SetAndGet()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/images/chem.jpg"
            };

            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/images/chem.jpg", course.TeachingMaterialImagePath);
        }

        [Fact]
        public void Course_NavigationProperties_DefaultNull()
        {
            var course = new Course();

            Assert.Null(course.Department);
            Assert.Null(course.Enrollments);
            Assert.Null(course.CourseAssignments);
        }
    }

    public class DepartmentTests
    {
        [Fact]
        public void Department_Properties_SetAndGet()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new System.DateTime(2007, 9, 1),
                InstructorID = 5
