using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Helpers
{
    public class PaginatedListTests
    {
        [Fact]
        public void Constructor_SetsPageIndexAndTotalPages()
        {
            var items = new List<int> { 1, 2, 3 };

            var list = new PaginatedList<int>(items, 10, 2, 3);

            Assert.Equal(2, list.PageIndex);
            Assert.Equal(4, list.TotalPages); // ceil(10/3) = 4
        }

        [Fact]
        public void Constructor_ContainsAllItems()
        {
            var items = new List<string> { "a", "b", "c" };

            var list = new PaginatedList<string>(items, 5, 1, 3);

            Assert.Equal(3, list.Count);
            Assert.Equal("a", list[0]);
            Assert.Equal("b", list[1]);
            Assert.Equal("c", list[2]);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

            Assert.False(list.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

            Assert.True(list.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 2, 5);

            Assert.False(list.HasNextPage); // TotalPages = ceil(10/5) = 2
        }

        [Fact]
        public void HasNextPage_FirstPage_WhenMorePages_ReturnsTrue()
        {
            var list = new PaginatedList<int>(new List<int> { 1 }, 10, 1, 5);

            Assert.True(list.HasNextPage); // TotalPages = 2, PageIndex = 1
        }

        [Fact]
        public void TotalPages_ExactDivision_CorrectCount()
        {
            var list = new PaginatedList<int>(new List<int>(), 20, 1, 5);

            Assert.Equal(4, list.TotalPages);
        }

        [Fact]
        public void TotalPages_WithRemainder_RoundsUp()
        {
            var list = new PaginatedList<int>(new List<int>(), 21, 1, 5);

            Assert.Equal(5, list.TotalPages);
        }

        [Fact]
        public void TotalPages_ZeroItems_ReturnsZero()
        {
            var list = new PaginatedList<int>(new List<int>(), 0, 1, 5);

            Assert.Equal(0, list.TotalPages);
        }

        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 20).AsQueryable();

            var page = PaginatedList<int>.Create(source, 2, 5);

            Assert.Equal(2, page.PageIndex);
            Assert.Equal(4, page.TotalPages);
            Assert.Equal(5, page.Count);
            Assert.Equal(6, page[0]);
            Assert.Equal(10, page[4]);
        }

        [Fact]
        public void Create_FirstPage_ContainsFirstItems()
        {
            var source = Enumerable.Range(1, 15).AsQueryable();

            var page = PaginatedList<int>.Create(source, 1, 5);

            Assert.Equal(1, page.PageIndex);
            Assert.Equal(3, page.TotalPages);
            Assert.Equal(5, page.Count);
            Assert.Equal(1, page[0]);
            Assert.Equal(5, page[4]);
        }

        [Fact]
        public void Create_LastPage_MayHaveFewerItems()
        {
            var source = Enumerable.Range(1, 7).AsQueryable();

            var page = PaginatedList<int>.Create(source, 2, 5);

            Assert.Equal(2, page.Count);
            Assert.Equal(6, page[0]);
            Assert.Equal(7, page[1]);
        }

        [Theory]
        [InlineData(1, 10, 3, false, true)]   // first page, has next
        [InlineData(2, 10, 3, true, true)]     // middle page, has both
        [InlineData(4, 10, 3, true, false)]    // last page, no next
        public void Navigation_VariousPages_CorrectFlags(int pageIndex, int totalCount, int pageSize, bool hasPrev, bool hasNext)
        {
            var list = new PaginatedList<int>(new List<int>(), totalCount, pageIndex, pageSize);

            Assert.Equal(hasPrev, list.HasPreviousPage);
            Assert.Equal(hasNext, list.HasNextPage);
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain static queue from previous tests
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE, "System");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Department", "1", EntityOperation.DELETE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_Delete_ContainsDeleteMessage()
        {
            _sut.SendNotification("Student", "5", "Jane", EntityOperation.DELETE, "Admin");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("deleted", notification.Message);
            Assert.Contains("Jane", notification.Message);
        }

        [Fact]
        public void SendNotification_Create_ContainsCreateMessage()
        {
            _sut.SendNotification("Course", "101", "Math 101", EntityOperation.CREATE, "Teacher");

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("created", notification.Message);
            Assert.StartsWith("New", notification.Message);
        }

        [Fact]
        public void SendNotification_Update_ContainsUpdateMessage()
        {
            _sut.SendNotification("Department", "3", "Science", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("updated", notification.Message);
            Assert.Contains("Science", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleSend_ReturnsFIFO()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);
            _sut.SendNotification("C", "3", EntityOperation.DELETE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();
            var third = _sut.ReceiveNotification();

            Assert.Equal("A", first.EntityType);
            Assert.Equal("B", second.EntityType);
            Assert.Equal("C", third.EntityType);
        }

        [Fact]
        public void ReceiveNotification_AfterDequeue_DoesNotReturnSameItem()
        {
            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.NotNull(first);
            Assert.Null(second);
        }

        [Fact]
        public void SendNotification_SetsCreatedAt()
        {
            var before = DateTime.Now;
            _sut.SendNotification("Test", "1", EntityOperation.CREATE);
            var after = DateTime.Now;

            var notification = _sut.ReceiveNotification();

            Assert.InRange(notification.CreatedAt, before, after);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op for in-memory implementation
            var exception = Record.Exception(() => _sut.MarkAsRead(1));

            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_WithNullDisplayName_UsesIdFormat()
        {
            _sut.SendNotification("Instructor", "7", null, EntityOperation.UPDATE, "Admin");

            var notification = _sut.ReceiveNotification();

            Assert.Contains("ID: 7", notification.Message);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesIdFormat()
        {
            _sut.SendNotification("Instructor", "7", "  ", EntityOperation.UPDATE, "Admin");

            var notification = _sut.ReceiveNotification();

            Assert.Contains("ID: 7", notification.Message);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            var service = new NotificationService();
            var ex = Record.Exception(() =>
            {
                service.Dispose();
                service.Dispose();
            });

            Assert.Null(ex);
        }
    }
}

