                LastName = "Smith",
                FirstMidName = "John",
                HireDate = DateTime.Parse("2000-01-15"),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);

            dept.InstructorID = instructor.ID;

            var course1 = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 4022,
                Title = "Microeconomics",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new System.Collections.Generic.List<Enrollment>(),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            context.Courses.AddRange(course1, course2);

            var student1 = new Student
            {
                ID = 1,
                LastName = "Alexander",
                FirstMidName = "Carson",
                EnrollmentDate = DateTime.Parse("2010-09-01"),
