+    public class BaseControllerTests
+    {
+        // We test BaseController through a concrete subclass
+        private class TestController : BaseController
+        {
+            public TestController(SchoolContext context) : base(context)
+            {
+            }
+
+            public void TestSendEntityNotification(string entityType, string entityId, EntityOperation operation)
+            {
+                SendEntityNotification(entityType, entityId, operation);
+            }
+
+            public void TestSendEntityNotificationWithName(string entityType, string entityId, string displayName, EntityOperation operation)
+            {
+                SendEntityNotification(entityType, entityId, displayName, operation);
+            }
+
+            public void TestDispose()
+            {
+                Dispose(true);
+            }
+        }
+
+        [Fact]
+        public void Constructor_SetsDbContext()
+        {
+            using var context = TestDbContextHelper.CreateContext();
+            using var controller = new TestController(context);
+
+            // Verify db is accessible through protected field - we can test by using it
+            Assert.NotNull(controller);
+        }
+
+        [Fact]
+        public void SendEntityNotification_WithoutDisplayName_DoesNotThrow()
+        {
+            using var context = TestDbContextHelper.CreateContext();
+            using var controller = new TestController(context);
+
+            var ex = Record.Exception(() =>
+                controller.TestSendEntityNotification("Student", "1", EntityOperation.CREATE));
+
+            Assert.Null(ex);
+        }
+
+        [Fact]
+        public void SendEntityNotification_WithDisplayName_DoesNotThrow()
+        {
+            using var context = TestDbContextHelper.CreateContext();
+            using var controller = new TestController(context);
+
+            var ex = Record.Exception(() =>
+                controller.TestSendEntityNotificationWithName("Student", "1", "John Doe", EntityOperation.UPDATE));
+
+            Assert.Null(ex);
+        }
+
+        [Fact]
+        public void SendEntityNotification_EnqueuesNotification()
+        {
+            using var context = TestDbContextHelper.CreateContext();
+            using var controller = new TestController(context);
+
+            // Drain queue
+            while (controller.notificationService.ReceiveNotification() != null) { }
+
+            controller.TestSendEntityNotificationWithName("Course", "42", "Math", EntityOperation.DELETE);
+
+            var notification = controller.notificationService.ReceiveNotification();
+            Assert.NotNull(notification);
+            Assert.Equal("Course", notification.EntityType);
+            Assert.Equal("42", notification.EntityId);
+            Assert.Contains("Math", notification.Message);
+            Assert.Contains("deleted", notification.Message);
+            Assert.Equal("System", notification.CreatedBy);
+        }
+
+        [Fact]
+        public void Dispose_DisposesContextAndService()
+        {
+            var context = TestDbContextHelper.CreateContext();
+            var controller = new TestController(context);
+
+            var ex = Record.Exception(() => controller.TestDispose());
+
+            Assert.Null(ex);
+        }
+
+        [Fact]
+        public void Dispose_CalledMultipleTimes_DoesNotThrow()
+        {
+            var context = TestDbContextHelper.CreateContext();
+            var controller = new TestController(context);
+
+            controller.TestDispose();
+            var ex = Record.Exception(() => controller.TestDispose());
+
+            Assert.Null(ex);
+        }
+    }
+}
