using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests
    {
        private SchoolContext CreateSeededContext() => TestDbContextHelper.CreateSeededContext();

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudents()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, "Alexander", null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.NotNull(model);
            Assert.Single(model);
            Assert.Equal("Alexander", model[0].LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, "Meredith", null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Meredith", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SortByNameDesc_OrdersDescending()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index("name_desc", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.True(string.Compare(model[0].LastName, model[1].LastName) > 0);
        }

        [Fact]
        public void Index_SortByDate_OrdersByEnrollmentDate()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index("Date", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.True(model[0].EnrollmentDate <= model[1].EnrollmentDate);
        }

        [Fact]
        public void Index_SortByDateDesc_OrdersByEnrollmentDateDescending()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index("date_desc", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.True(model[0].EnrollmentDate >= model[1].EnrollmentDate);
        }

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAsc()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.True(string.Compare(model[0].LastName, model[1].LastName) <= 0);
        }

        [Fact]
        public void Index_NewSearch_ResetsToPage1()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, "Alexander", null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_CurrentFilter_UsedWhenSearchStringNull()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index(null, "Alexander", null, 1) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
