        public void Index_SearchByFirstName_FiltersStudents()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index(null, null, "Meredith", null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as PaginatedList<Student>;
            Assert.Single(model);
            Assert.Equal("Meredith", model[0].FirstMidName);
        }

        [Fact]
        public void Index_SortByNameDesc_OrdersDescending()
        {
            using var context = CreateSeededContext();
            using var controller = new StudentsController(context);

            var result = controller.Index("name_desc", null, null, null) as ViewResult;

            var model = result.Model as PaginatedList<Student>;
            Assert.True(string.Compare(model[0].LastName, model[1].LastName) > 0);
        }

