using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests
    {
        [Fact]
        public void Index_NoParams_ReturnsViewWithInstructors()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Index(null, null) as ViewResult;

            Assert.NotNull(result);
            var model = result.Model as ContosoUniversity.Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model);
            Assert.Single(model.Instructors);
        }

        [Fact]
        public void Index_WithInstructorId_PopulatesCourses()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            var instructorId = context.Instructors.First().ID;
            using var controller = new InstructorsController(context);

            var result = controller.Index(instructorId, null) as ViewResult;

            var model = result.Model as ContosoUniversity.Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model.Courses);
            Assert.Single(model.Courses);
        }

        [Fact]
        public void Index_WithCourseId_PopulatesEnrollments()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            var instructorId = context.Instructors.First().ID;
            using var controller = new InstructorsController(context);

            var result = controller.Index(instructorId, 1050) as ViewResult;

            var model = result.Model as ContosoUniversity.Models.SchoolViewModels.InstructorIndexData;
            Assert.NotNull(model.Enrollments);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            var instructorId = context.Instructors.First().ID;
            using var controller = new InstructorsController(context);

            var result = controller.Details(instructorId) as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.Equal("Smith", instructor.LastName);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Details(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Details_NotFound_ReturnsNotFound()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Details(99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithInstructor()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Create() as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.NotNull(instructor);
            Assert.NotNull(instructor.CourseAssignments);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);
            var instructor = new Instructor
            {
                LastName = "NewInstructor",
                FirstMidName = "Test",
                HireDate = System.DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, null) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(2, context.Instructors.Count());
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AddsAssignments()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);
            var instructor = new Instructor
            {
                LastName = "NewInstructor",
                FirstMidName = "Test",
                HireDate = System.DateTime.Parse("2020-01-01")
            };

            var result = controller.Create(instructor, new[] { "1050" }) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            var saved = context.Instructors.First(i => i.LastName == "NewInstructor");
            Assert.NotNull(saved);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);
            controller.ModelState.AddModelError("LastName", "Required");
            var instructor = new Instructor
            {
                HireDate = System.DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            var result = controller.Create(instructor, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithInstructor()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            var instructorId = context.Instructors.First().ID;
            using var controller = new InstructorsController(context);

            var result = controller.Delete(instructorId) as ViewResult;

            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.Equal("Smith", instructor.LastName);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Delete(null) as StatusCodeResult;

            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            using var controller = new InstructorsController(context);

            var result = controller.Delete(99999) as NotFoundResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_RemovesInstructorAndRedirects()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            var instructorId = context.Instructors.First().ID;
            using var controller = new InstructorsController(context);

            var result = controller.DeleteConfirmed(instructorId) as RedirectToActionResult;

            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Empty(context.Instructors);
        }

        [Fact]
        public void DeleteConfirmed_ClearsDepartmentAdministrator()
        {
            using var context = TestDbContextHelper.CreateSeededContext();
            var instructorId = context.Instructors.First().ID;
            // Verify department initially has InstructorID set
            var deptBefore = context.Departments.First();
            Assert.Equal(instructorId, deptBefore.InstructorID);

            using var controller = new InstructorsController(context);
            controller.DeleteConfirmed(instructorId);

            var deptAfter = context.Departments.First();
            Assert.Null(deptAfter.InstructorID);
        }
    }
}

